from typing import Dict, Any, Tuple
import numpy as np
from sklearn.ensemble import GradientBoostingRegressor

from backend.app.schemas.prediction import ContributingFactors

SAFETY_DISCLAIMER = (
    "NOTICE: This Remaining Useful Life (RUL) estimate is generated by an AI research prototype "
    "based on synthetic degradation curves, visual defect records, and IoT vibration trends. "
    "It is NOT a certified professional structural engineering evaluation and must not be used "
    "as the sole basis for life-safety or structural sign-off without on-site licensed PE inspection."
)

NOMINAL_DESIGN_LIFE = {
    "steel": 100.0,
    "reinforced_concrete": 75.0,
    "prestressed_concrete": 80.0,
    "masonry": 120.0,
}

ENVIRONMENT_MULTIPLIERS = {
    "rural": 1.00,
    "urban": 1.15,
    "industrial": 1.35,
    "coastal": 1.50,
    "marine": 1.75,
}


class RULDegradationModel:
    """
    Remaining Useful Life (RUL) Prediction Model.
    Utilizes physics-informed degradation modeling combined with Gradient Boosting regression
    to estimate structural lifespan and health degradation.
    """

    def __init__(self):
        self.model = GradientBoostingRegressor(
            n_estimators=100,
            learning_rate=0.08,
            max_depth=4,
            random_state=42,
        )
        self._train_baseline_degradation_regressor()

    def _train_baseline_degradation_regressor(self):
        """Train the regressor on a physics-informed synthetic degradation distribution."""
        np.random.seed(42)
        n_samples = 3000

        # Feature matrix:
        # 0: age_ratio (age / design_life) [0.0 - 1.3]
        # 1: defect_penalty_pct [0.0 - 50.0]
        # 2: vibration_rms [0.5 - 12.0 mm/s]
        # 3: env_multiplier [1.0 - 1.8]
        # 4: cyclic_ratio [0.3 - 3.0]
        age_ratio = np.random.uniform(0.05, 1.25, n_samples)
        defect_pen = np.random.exponential(scale=8.0, size=n_samples)
        defect_pen = np.clip(defect_pen, 0.0, 50.0)
        vib_rms = np.random.gamma(shape=2.5, scale=1.2, size=n_samples)
        vib_rms = np.clip(vib_rms, 0.5, 14.0)
        env_mult = np.random.choice([1.0, 1.15, 1.35, 1.50, 1.75], size=n_samples)
        cyclic_ratio = np.random.uniform(0.5, 2.5, size=n_samples)

        # Target: remaining_fraction_of_life (0.0 to 1.0)
        # Physics degradation function:
        # Base linear age consumption + accelerated non-linear damage from vibrations and defects
        damage = (
            (age_ratio ** 1.3) * 0.50
            + (defect_pen / 50.0) * 0.25
            + ((vib_rms - 1.0) / 10.0) * 0.15 * (cyclic_ratio ** 0.8)
        ) * env_mult

        remaining_fraction = np.clip(1.0 - damage, 0.02, 0.98)

        X = np.column_stack([age_ratio, defect_pen, vib_rms, env_mult, cyclic_ratio])
        y = remaining_fraction
        self.model.fit(X, y)

    def predict(
        self,
        construction_year: int,
        material_type: str,
        current_year: int,
        defect_penalty_pct: float,
        vibration_rms: float,
        environmental_condition: str,
        daily_traffic_volume: int,
    ) -> Tuple[float, float, str, ContributingFactors, Dict[str, Any]]:
        """
        Calculates estimated RUL in years, health score (0-100), risk level, and contributing factors.
        """
        material_clean = material_type.lower().replace(" ", "_")
        design_life = NOMINAL_DESIGN_LIFE.get(material_clean, 75.0)

        age = max(1.0, float(current_year - construction_year))
        age_ratio = min(1.3, age / design_life)

        env_mult = ENVIRONMENT_MULTIPLIERS.get(environmental_condition.lower(), 1.15)
        cyclic_ratio = float(daily_traffic_volume) / 25000.0

        features = np.array([[age_ratio, defect_penalty_pct, vibration_rms, env_mult, cyclic_ratio]])
        pred_fraction = float(self.model.predict(features)[0])
        pred_fraction = max(0.01, min(0.98, pred_fraction))

        # RUL in years = remaining fraction * design life
        rul_years = round(pred_fraction * design_life, 1)

        # Health score: 0 to 100 scale
        health_score = round(float(np.clip(pred_fraction * 100.0, 5.0, 99.5)), 1)

        # Risk level classification
        if health_score < 40.0 or rul_years < 3.0:
            risk_level = "CRITICAL"
        elif health_score < 60.0 or rul_years < 10.0:
            risk_level = "HIGH"
        elif health_score < 80.0 or rul_years < 20.0:
            risk_level = "MODERATE"
        else:
            risk_level = "LOW"

        # Factors breakdown
        factors = ContributingFactors(
            structural_age_years=round(age, 1),
            design_life_years=design_life,
            age_depreciation_pct=round(age_ratio * 100.0, 1),
            defect_severity_impact_pct=round(defect_penalty_pct, 1),
            vibration_fatigue_impact_pct=round(min(100.0, (vibration_rms / 6.0) * 30.0), 1),
            environmental_harshness_factor=env_mult,
            cyclic_stress_factor=round(cyclic_ratio, 2),
        )

        metadata = {
            "model_type": "GradientBoostingRegressor (Physics-Informed Structural Degradation)",
            "training_dataset": "Synthetic Bridge & Dam Failure Curves (AASHTO / Eurocode baselines)",
            "mode": "PROTOTYPE_ESTIMATE",
            "version": "1.0.0",
        }

        return rul_years, health_score, risk_level, factors, metadata


# Singleton instance
rul_model = RULDegradationModel()
